 refresh('str-property-management-fees', 'STR Management Fees: Compare Quotes Before Buying', 'Short-Term Rental Management Fees', 'Compare STR management quotes before buying: fee bases, included work, decision rights, opening cash and a worked higher-percentage versus lower-cost example.', BODY, FAQ, '2026-08-11', 'data-management-fees-review-link', 'Compare the <a href="/blog/str-property-management-fees/">management quote register and service-fee cash worksheet</a>. Operating labels do not establish tax eligibility or a funded opening plan.')
 root = Path(__file__).resolve().parents[1]
 p = root/'blog/str-property-management-fees/index.html'
 s = subprocess.check_output(['node','--input-type=module','-e', "import {readFileSync} from 'node:fs'; import {expandPreclosingKeywords} from './preclosing_keywords.mjs'; const p='blog/str-property-management-fees/index.html'; process.stdout.write(expandPreclosingKeywords(readFileSync(p,'utf8'),p));"], cwd=root, text=True)
 p.write_text(s)
